SELECT od.id AS detail_id, o.id AS order_id, od.massagist_id, od.shop_id, TRIM(c.phone) AS phone, DATE(od.end_time) AS service_date, DATE(o.pay_time) AS pay_date, od.duration, COALESCE(p.coefficient, 1.00) AS project_coefficient, od.project_id, COALESCE(p.title, o.product_title) AS project_title, o.parts AS parts
